-- 初始 schema（PostgreSQL 方言）
--
-- 这套迁移会同时应用到两个库（platform / game_7010544），所以全部用
-- `IF NOT EXISTS`，幂等。真正的 277 张表由 `data/sql/platform.sql` 平移，
-- 这里只建仓储层当前用到的核心表，保证服务能启动、单测能跑。
--
-- MySQL → PostgreSQL 的 DDL 差异（平移时逐条对照）：
--   TINYINT(1)          → BOOLEAN
--   INT UNSIGNED        → INTEGER（+ CHECK (col >= 0)）
--   BIGINT AUTO_INCREMENT → BIGINT GENERATED BY DEFAULT AS IDENTITY
--   DATETIME            → TIMESTAMPTZ
--   JSON                → JSONB
--   ENGINE=InnoDB ...   → 删除（含字符集、ROW_FORMAT）
--   表/列名反引号        → 双引号或裸标识符

-- ---------------------------------------------------------------- 账号（platform 库）
CREATE TABLE IF NOT EXISTS "user" (
    user_id      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username     VARCHAR(64)  NOT NULL UNIQUE,
    password     VARCHAR(128) NOT NULL,
    channel      VARCHAR(32)  NOT NULL DEFAULT '',
    create_time  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    last_login   TIMESTAMPTZ
);

-- ---------------------------------------------------------------- 角色（game 库）
CREATE TABLE IF NOT EXISTS player (
    player_id   BIGINT PRIMARY KEY,
    user_id     BIGINT NOT NULL,
    name        VARCHAR(64) NOT NULL,
    level       INTEGER NOT NULL DEFAULT 1,
    exp         BIGINT  NOT NULL DEFAULT 0,
    vip         INTEGER NOT NULL DEFAULT 0,
    last_login  TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_player_user ON player (user_id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_player_name ON player (name);

-- ---------------------------------------------------------------- 背包
CREATE TABLE IF NOT EXISTS item (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    player_id   BIGINT  NOT NULL,
    template_id INTEGER NOT NULL,
    num         BIGINT  NOT NULL DEFAULT 0 CHECK (num >= 0)
);
-- `ON CONFLICT (player_id, template_id)` 依赖这个唯一约束
CREATE UNIQUE INDEX IF NOT EXISTS uq_item_player_tpl ON item (player_id, template_id);

-- ---------------------------------------------------------------- 邮件
CREATE TABLE IF NOT EXISTS mail (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    player_id   BIGINT NOT NULL,
    title       VARCHAR(128) NOT NULL,
    content     TEXT NOT NULL DEFAULT '',
    attach      JSONB,
    claimed     BOOLEAN NOT NULL DEFAULT FALSE,
    send_time   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_mail_player ON mail (player_id, claimed);

-- ---------------------------------------------------------------- 公会
CREATE TABLE IF NOT EXISTS guild (
    guild_id    BIGINT PRIMARY KEY,
    name        VARCHAR(64) NOT NULL,
    leader_id   BIGINT NOT NULL,
    level       INTEGER NOT NULL DEFAULT 1,
    notice      TEXT NOT NULL DEFAULT '',
    create_time TIMESTAMPTZ NOT NULL DEFAULT now()
);
